import fs from 'node:fs/promises';import{db}from'./reply-runtime-20261015.mjs';
const dir='artifacts/reply-review-20261019-weekend';const contractors=await db('subcontractors',{select:'*',limit:'1000'});const selected=contractors.filter(c=>['6478389509','5198590747','5196196917'].some(p=>String(c.phone).replace(/\D/g,'').endsWith(p)));await fs.writeFile(dir+'/contractor-context.json',JSON.stringify(selected,null,2));console.log(JSON.stringify(selected.map(c=>({id:c.id,name:c.company_name,phone:c.phone,email:c.email,notes:c.notes}))))
const review=JSON.parse(await fs.readFile(dir+'/review.json'));
for(const name of ['GEORGE NASRALLAH','JULIETTE TALANI']){const r=review.rows.find(r=>r.contact.name===name);const last=r.thread.at(-1);const url=last.notes.match(/https:\/\/[^\]\s]+/)?.[0];if(!url)continue;const response=await fetch(url);if(!response.ok)throw Error('Attachment fetch failed '+response.status);const path=dir+'/'+(name.startsWith('GEORGE')?'george.png':'juliette.amr');await fs.writeFile(path,Buffer.from(await response.arrayBuffer()));console.log(path);}
